class Solution:
    def missingNumber(self, nums: List[int]) -> int:
        res = len(nums)
        for i, n in enumerate(nums):
            res ^= (i ^ n)
        return res

reference_solution.javascript:
function missingNumber(nums) {
    let res = nums.length;
    for (let i = 0; i < nums.length; i++) {
        res ^= (i ^ nums[i]);
    }
    return res;
}
